  4815    start = snode->s;
  4816    end   = snode->end;
  4817    if (start >= end) return 0;
  4818
  4819    in_look_behind = (state & IN_LOOK_BEHIND) != 0;
  4820    enc = reg->enc;
  4821
  4822    list = sn = NULL_NODE;
  4823    p = start;
  4824    while (p < end) {
  4825      n = ONIGENC_GET_CASE_FOLD_CODES_BY_STR(enc, reg->case_fold_flag, p, end,
  4826                                             items);
  4827      if (n < 0) {
  4828        r = n;
  4829        goto err;
  4830      }
  4831
  4832      one_len = enclen(enc, p);
  4833      if (n == 0) {
  4834        q = p + one_len;
  4835        r = unravel_cf_string_add(&list, &sn, p, q, 0 /* flag */);
  4836        if (r != 0) goto err;
  4837      }
  4838      else {
  4839        if (in_look_behind != 0) {
  4840          q = p + one_len;
  4841          if (items[0].byte_len != one_len) {
  4842            r = ONIGENC_GET_CASE_FOLD_CODES_BY_STR(enc, reg->case_fold_flag, p, q,
  4843                                                   items);
  4844            if (r < 0) goto err;
  4845            n = r;
  4846          }
  4847          r = unravel_cf_look_behind_add(&list, &sn, n, items, enc, p, one_len);
  4848          if (r != 0) goto err;
  4849        }
  4850        else {
  4851          get_min_max_byte_len_case_fold_items(n, items, &min_len, &max_len);
  4852          if (min_len != max_len) {
  4853            r = ONIGERR_PARSER_BUG;
  4854            goto err;
  4855          }
  4856
  4857          q = p + max_len;
  4858          r = unravel_cf_string_alt_or_cc_add(&list, n, items, max_len, enc,
  4859                                              reg->case_fold_flag, p, q);
  4860          if (r != 0) goto err;
  4861          sn = NULL_NODE;
  4862        }
  4863      }
  4864
  4865      p = q;
  4866    }
  4867
  4868    if (IS_NOT_NULL(list)) {
  4869      if (node_list_len(list) == 1) {
  4870        node_swap(node, NODE_CAR(list));
  4871      }
  4872      else {
  4873        node_swap(node, list);
  4874      }
